function wifiPage(){return{status:null,loading:!0,error:"",saving:!1,okmsg:"",async fetchStatus(){try{var r=await fetch("/api/wifi/status",{cache:"no-store"});this.status=await r.json(),this.error=""}catch(e){this.error="Failed to load status"}finally{this.loading=!1}},connected(){var st;return!(!this.status||"connected"!==(st=(this.status.state||"").toLowerCase())&&"wifi_connected"!==st&&!this.status.ip)},async save(ssid,psk){this.saving=!0,this.okmsg="",this.error="";try{var j=await(await fetch("/api/wifi/save",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({ssid:ssid,psk:psk})})).json();j.ok?(this.okmsg=j.message||"Saved",setTimeout(()=>this.fetchStatus(),600)):this.error=j.message||"Save failed"}catch(_){this.error="Save failed"}finally{this.saving=!1}},init(){this.fetchStatus(),setInterval(()=>this.fetchStatus(),5e3)}}}